/**
 * Ambient types for the two third-party modules the spell checker loads.
 *
 * This file has no imports or exports on purpose: `declare module` blocks only
 * take effect in a global script. It is included by tsconfig's `**\/*.ts` glob.
 *
 * The two data files come from the `dictionary-en` package (v4.0.0, MIT AND
 * BSD — the en_US Hunspell dictionary derived from SCOWL). They are imported
 * as plain strings by webpack's `asset/source` rule configured in
 * `next.config.mjs`; the package's own entry point reads them through
 * `node:fs/promises` and so cannot be used in a browser.
 */
declare module "dictionary-en/index.aff" {
  /** The Hunspell affix file as text. */
  const aff: string;
  export default aff;
}

declare module "dictionary-en/index.dic" {
  /** The Hunspell dictionary file as text (one entry per line). */
  const dic: string;
  export default dic;
}

/**
 * `nspell` v2.1.5 ships no types (MIT, ~41 KB unpacked, no dependencies other
 * than `is-buffer`). These declarations cover exactly the API this project
 * uses, and nothing more.
 */
declare module "nspell" {
  export interface NSpell {
    /** True when the dictionary contains `word`. */
    correct(word: string): boolean;
    /** Spelling suggestions, generated by character edits checked against the dictionary. */
    suggest(word: string): string[];
    /** Detailed result: correctness, whether the word is forbidden, whether it is a warning word. */
    spell(word: string): { correct: boolean; forbidden: boolean; warn: boolean };
    /** Add a word (or, with `model`, a word following that word's affix rules). */
    add(word: string, model?: string): NSpell;
    /** Remove a word. */
    remove(word: string): NSpell;
    /** The word-character class from the affix file, e.g. `"0123456789"`. */
    wordCharacters(): string;
    /** Add an extra Hunspell dictionary file. */
    dictionary(dic: string): NSpell;
    /** Add a personal dictionary file. */
    personal(dic: string): NSpell;
  }

  /**
   * Build a spelling context from an affix file and (optionally) a dictionary
   * file, both as text.
   */
  export default function nspell(aff: string, dic?: string): NSpell;
}
